#!/bin/sh
set -eu
share="/Volumes/My Shared Files/ClaudeShield-Exchange"
[ -d "$share/01_在研课题_Projects" ] || { echo "请在已挂载交换卷的 macOS 客机执行"; exit 1; }
python3 - "$share" <<'PY'
import base64, ctypes, ctypes.util, fcntl, hashlib, json, os, re, shutil, sys, tempfile
from pathlib import Path

share = Path(sys.argv[1])
dest = Path.home() / "Library/Application Support/Claude"
payloads = {
    "state_client.py": base64.b64decode(''),
    "mcp_filesystem_server.py": base64.b64decode(''),
}

# 1. 更新客机本地 ~/Library/Application Support/Claude/ 下的 MCP 与 state_client
if dest.is_dir():
    backup = Path(tempfile.mkdtemp(dir=dest, prefix="pre-state-"))
    for name, body in payloads.items():
        compile(body, name, "exec")
        if (dest / name).exists():
            shutil.copy2(dest / name, backup / name)
        with tempfile.NamedTemporaryFile(dir=dest, delete=False) as f:
            f.write(body); f.flush(); os.fsync(f.fileno())
        os.replace(f.name, dest / name)
    print("[OK] 客机本地 MCP 与 state_client 已升级（备份目录:", backup.name, "）")

# 2. 从客机侧修复共享盘 00_全局中枢_Hub/scripts/ 下因宿主机 os.replace 失效的 namei 缓存条目
scripts_dir = share / "00_全局中枢_Hub/scripts"
for name, body in payloads.items():
    target = scripts_dir / name
    try:
        target.unlink(missing_ok=True)
    except OSError:
        pass
    try:
        with open(target, "wb") as f:
            f.write(body); f.flush(); os.fsync(f.fileno())
    except OSError:
        pass

# 3. 强制冲刷客机 XNU 内核对各课题 01_PROJECT_STATE.md 与 _bus/reply.md 的 UBC 内存页缓存并自愈校验
libc = ctypes.CDLL(ctypes.util.find_library("c"), use_errno=True)
libc.mmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_longlong]
libc.mmap.restype = ctypes.c_void_p
libc.msync.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int]
libc.msync.restype = ctypes.c_int
libc.munmap.argtypes = [ctypes.c_void_p, ctypes.c_size_t]
libc.munmap.restype = ctypes.c_int
F_NOCACHE = getattr(fcntl, "F_NOCACHE", 48)

def purge_and_read(p: Path) -> bytes:
    fd = os.open(p, os.O_RDONLY)
    try:
        try: fcntl.fcntl(fd, F_NOCACHE, 1)
        except OSError: pass
        sz = os.fstat(fd).st_size
        if sz > 0:
            addr = libc.mmap(None, sz, 0x01, 0x0001, fd, 0)
            if addr and addr != ctypes.c_void_p(-1).value:
                libc.msync(ctypes.c_void_p(addr), sz, 0x0002)
                libc.munmap(ctypes.c_void_p(addr), sz)
        chunks = []
        while True:
            b = os.read(fd, 65536)
            if not b: break
            chunks.append(b)
        return b"".join(chunks)
    finally:
        os.close(fd)

for proj in sorted((share / "01_在研课题_Projects").glob("P*_*")):
    if not proj.is_dir(): continue
    st_file = proj / "_control/01_PROJECT_STATE.md"
    cache_dir = proj / "_control/.state_cache"
    if st_file.is_file():
        data = purge_and_read(st_file)
        sha = hashlib.sha256(data).hexdigest()
        # 若 .state_cache 中有最新快照且哈希不一致，由客机 VFS 原地刷入以彻底同步客机 UBC
        if cache_dir.is_dir():
            snaps = [cache_dir / n for n in os.listdir(cache_dir) if re.fullmatch(r"[a-f0-9]{64}\.md", n)]
            if snaps:
                latest = max(snaps, key=lambda x: x.stat().st_mtime_ns)
                if latest.stem != sha:
                    sdata = purge_and_read(latest)
                    if hashlib.sha256(sdata).hexdigest() == latest.stem:
                        with open(st_file, "r+b") as wf:
                            wf.seek(0); wf.write(sdata); wf.truncate(); wf.flush(); os.fsync(wf.fileno())
                        data = purge_and_read(st_file)
                        sha = hashlib.sha256(data).hexdigest()
        print(f"[OK] {proj.name} 状态文件已冲刷缓存并核实 -> sha256={sha[:16]}... ({len(data)} bytes)")
    rep_file = proj / "_bus/reply.md"
    if rep_file.is_file():
        rdata = purge_and_read(rep_file)
        print(f"[OK] {proj.name} _bus/reply.md 已冲刷缓存 -> {len(rdata)} bytes")
PY
